class L(list):
 def __iter__(self): print("iter"); return iter((11,13))
 def __getitem__(self,key): return 17
 def __len__(self): return 19
a=L((7,9))
print(next(iter(a)),a[0],len(a),list.__getitem__(a,0),list.__len__(a))

class L(list): pass
a=L((7,9))
def items():
 yield 11
 raise ValueError("failed")
try: list.__init__(a,items())
except ValueError: print(len(a),a[0])

class S(set): pass
s=S((7,9))
b=s
s|={11}
s&={7,11}
print(s is b,len(b),7 in b,11 in b,type(s) is S)

class S(set): pass
s=S((7,9))
def items():
 print("before",len(s))
 yield 11
 print("after",len(s),11 in s)
 raise ValueError("failed")
try: set.__init__(s,items())
except ValueError: print(len(s),11 in s)

